import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,lstatSync,symlinkSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {spawnSync} from 'node:child_process';
import {PRELAUNCH_POLICY,validatePrelaunchRequest,validatePrelaunchObservation,validateNewAttempt,recoverPrelaunch} from './prelaunch-recovery-policy.mjs';
import {exclusiveRecord,reserveLaunchOnce,copyRetainedPacket} from './prelaunch-recovery-server.mjs';
import {remotePrelaunchSource} from './prelaunch-recovery.mjs';
const sha=n=>n.repeat(40),hash=n=>n.repeat(64),id=n=>`${n.repeat(8)}-${n.repeat(4)}-4${n.repeat(3)}-8${n.repeat(3)}-${n.repeat(12)}`;
function fixture(){
 const request={policy:PRELAUNCH_POLICY,source:sha('1'),baseline:sha('2'),verifier:sha('3'),witnessFingerprint:hash('4'),qualificationRunId:42,oldInstallId:id('1'),baselineInstallId:id('2'),oldAuthorizationSha256:hash('5'),baselineAuthorizationSha256:hash('6'),currentSha256:hash('7'),lastOkSha256:hash('8'),oldPreflightSha256:hash('9'),oldAcknowledgementSha256:hash('a'),failureSha256:hash('b'),bundleOwnerSha256:hash('c'),lease:{batch:id('3'),epoch:2}};
 const old={installId:request.oldInstallId,source:request.source,baseline:request.baseline,witnessFingerprint:request.witnessFingerprint,controller:sha('5'),controllerBranch:'main',baselineBuildId:'baseline-build',environmentSha256:hash('d'),runId:10,runAttempt:1,runCreatedAt:'2026-11-19T00:00:00Z',producerStartedAt:'2026-11-19T00:01:00Z',producerCompletedAt:'2026-11-19T00:02:00Z',artifact:{id:11,digest:'sha256:'+hash('e')},build:{nextBuildId:'original-build',buildRecordId:id('4')},issuedAt:'2026-11-19T01:00:00Z',expiresAt:'2026-11-19T01:30:00Z'};
 const grant={...structuredClone(old),installId:id('5'),issuedAt:'2026-11-19T02:00:00Z',expiresAt:'2026-11-19T02:30:00Z'};
 const observation={policy:PRELAUNCH_POLICY,source:request.source,baseline:request.baseline,oldInstallId:request.oldInstallId,oldAuthorizationSha256:request.oldAuthorizationSha256,baselineAuthorizationSha256:request.baselineAuthorizationSha256,currentSha256:request.currentSha256,lastOkSha256:request.lastOkSha256,lease:request.lease,noNativeBegin:true,noNativeProcess:true,oldUnlaunched:true,oldGrantNotRevoked:true,pending:request.source,compiledMetadataSha256:hash('a'),packetSha256:hash('b'),baselineManifestSha256:hash('c'),environmentSha256:old.environmentSha256,compiledBytesVerified:true,releaseAuthorized:false};
 const evidence={sha:request.source,baseline:request.baseline,fingerprint:request.witnessFingerprint,verificationController:request.verifier,result:'PASS'};
 return {request,old,grant,observation,evidence};
}
const temporary=fn=>{const dir=mkdtempSync(join(tmpdir(),'aihr-prelaunch-'));try{return fn(dir);}finally{rmSync(dir,{recursive:true,force:true});}};
test('closed private request preserves distinct source/verifier/baseline and known lease',()=>{const f=fixture();assert.equal(validatePrelaunchRequest(f.request),f.request);for(const change of [{extra:true},{policy:'other'},{baseline:f.request.source},{oldInstallId:f.request.baselineInstallId},{lease:{batch:id('3'),epoch:0}}])assert.throws(()=>validatePrelaunchRequest({...f.request,...change}));});
for(const key of ['compiledBytesVerified','noNativeBegin','noNativeProcess','oldUnlaunched','oldGrantNotRevoked'])test('refuses absent '+key,()=>{const f=fixture();assert.throws(()=>validatePrelaunchObservation({...f.observation,[key]:false},f.request));});
for(const key of ['oldAuthorizationSha256','baselineAuthorizationSha256','currentSha256','lastOkSha256','pending','lease'])test('refuses changed '+key,()=>{const f=fixture();assert.throws(()=>validatePrelaunchObservation({...f.observation,[key]:key==='lease'?{batch:id('3'),epoch:3}:hash('f')},f.request));});
test('new independent grant does not renew or mutate original authority',()=>{const f=fixture(),bytes=JSON.stringify(f.old);validateNewAttempt(f.grant,f.old,f.request);assert.equal(JSON.stringify(f.old),bytes);for(const key of ['source','controller','baseline','environmentSha256','witnessFingerprint','build','artifact','producerCompletedAt'])assert.throws(()=>validateNewAttempt({...f.grant,[key]:'changed'},f.old,f.request));assert.throws(()=>validateNewAttempt({...f.grant,installId:f.old.installId},f.old,f.request));});
function ports(f,events){return {frozen:async()=>events.push('frozen'),proveLocalFailure:async()=>events.push('dead-original'),observe:async()=>{events.push('compiled-bytes');return f.observation;},reauthenticate:async()=>{events.push('all-api-artifacts');return f.evidence;},cheapFence:async()=>events.push('fast-fence'),newGrant:async()=>{events.push('new-independent-grant');return f.grant;},linkAndCopy:async()=>{events.push('exclusive-link-and-copy');return {installId:f.grant.installId,oldInstallId:f.old.installId,copyVerified:true,releaseAuthorized:false};},reserveAndLaunch:async()=>{events.push('reserve-single-native-launch');return {installId:f.grant.installId,launchReserved:true};},arrive:async()=>{events.push('canonical-arrival');return {arrived:true};}};}
test('whole metadata reauthentication and byte proof precede new grant; canonical arrival follows single launch',async()=>{const f=fixture(),events=[];assert.deepEqual(await recoverPrelaunch({request:f.request,oldGrant:f.old,ports:ports(f,events)}),{arrived:true});assert(events.indexOf('all-api-artifacts')<events.indexOf('new-independent-grant'));assert(events.indexOf('compiled-bytes')<events.indexOf('new-independent-grant'));assert.equal(events.filter(x=>x==='all-api-artifacts').length,1);assert(events.indexOf('exclusive-link-and-copy')<events.indexOf('reserve-single-native-launch'));assert.equal(events.filter(x=>x==='reserve-single-native-launch').length,1);});
for(const failure of ['proveLocalFailure','observe','reauthenticate','cheapFence'])test('no grant/launch after failed '+failure,async()=>{const f=fixture(),events=[],p=ports(f,events);p[failure]=async()=>{throw Error('actual refusal');};await assert.rejects(recoverPrelaunch({request:f.request,oldGrant:f.old,ports:p}),/actual refusal/);assert(!events.includes('new-independent-grant'));assert(!events.includes('reserve-single-native-launch'));});
test('does not retry or issue another identity after uncertain link/copy',async()=>{const f=fixture(),events=[],p=ports(f,events);p.linkAndCopy=async()=>{events.push('uncertain');throw Error('lost reply');};await assert.rejects(recoverPrelaunch({request:f.request,oldGrant:f.old,ports:p}),/lost reply/);assert.equal(events.filter(x=>x==='new-independent-grant').length,1);assert(!events.includes('reserve-single-native-launch'));});
test('exclusive durable old key cannot be overwritten by another new identity',()=>temporary(dir=>{const path=join(dir,'old.json');exclusiveRecord(path,Buffer.from('first'));assert.throws(()=>exclusiveRecord(path,Buffer.from('second')),/EEXIST/);assert.equal(readFileSync(path,'utf8'),'first');assert.equal(lstatSync(path).mode&0o777,0o600);}));
test('uncertain launch remains permanently reserved and cannot launch twice',()=>temporary(dir=>{const path=join(dir,'old.launch.json');let launches=0;assert.throws(()=>reserveLaunchOnce(path,Buffer.from('reservation'),()=>{launches++;throw Error('lost response');}),/lost response/);assert.throws(()=>reserveLaunchOnce(path,Buffer.from('new'),()=>launches++),/EEXIST/);assert.equal(launches,1);assert.equal(readFileSync(path,'utf8'),'reservation');}));
test('retained packet copy is byte-exact, owner-private and leaves all original members unchanged',()=>temporary(dir=>{const from=join(dir,'old'),to=join(dir,'new');mkdirSync(from,{mode:0o700});mkdirSync(to,{mode:0o700});mkdirSync(join(from,'bytes'),{mode:0o700});const names=['build-provenance.json','successful-build.json','system-testing.json','bytes/build-bundle-files.json','bytes/build-bundle.tar.gz'];for(const name of names)writeFileSync(join(from,name),'original:'+name,{mode:0o600});copyRetainedPacket(from,to);for(const name of names){assert.equal(readFileSync(join(from,name),'utf8'),'original:'+name);assert.deepEqual(readFileSync(join(to,name)),readFileSync(join(from,name)));assert.equal(lstatSync(join(to,name)).mode&0o777,0o600);assert.equal(lstatSync(join(to,name)).nlink,1);}assert.throws(()=>copyRetainedPacket(from,to),/EEXIST/);}));
test('packet copy refuses symlink members without following them',()=>temporary(dir=>{const from=join(dir,'old'),to=join(dir,'new');mkdirSync(from,{mode:0o700});mkdirSync(to,{mode:0o700});writeFileSync(join(dir,'foreign'),'secret',{mode:0o600});symlinkSync(join(dir,'foreign'),join(from,'build-provenance.json'));assert.throws(()=>copyRetainedPacket(from,to),/Bounded real file/);assert.equal(readFileSync(join(dir,'foreign'),'utf8'),'secret');}));
test('remote module assembly is syntactically valid and retains exact canonical guarded owners',()=>{const bytes=name=>readFileSync(new URL(name,import.meta.url));const server=bytes('./prelaunch-recovery-server.mjs'),policy=bytes('./prelaunch-recovery-policy.mjs');const code=remotePrelaunchSource(server,policy);const checked=spawnSync(process.execPath,['--input-type=module','--check'],{input:code,encoding:'utf8'});assert.equal(checked.status,0,checked.stderr);assert(code.includes('coordinator.py'));assert(code.includes('verify-active-directory'));assert(code.includes('official.buildLaunchCommand'));assert(!code.includes('strictPendingCommand'));assert.throws(()=>remotePrelaunchSource(Buffer.from('not the server'),policy));});
